"""Recover a whole attached Bundle perimeter without changing its mouths.

This is a construction primitive, not a published network surface. Two complete
member corridors and their two original patch bridges define the boundary.
Inner pavement boundaries may cross; the outside perimeter must remain simple.
Every returned point refers to an existing pavement vertex by exact identity.
"""
import bpy
from . import curved_separator_boundary_nodes as closed
from . import curved_free_separator_boundary_nodes as checks
from . import curved_junction_nodes as boundary
from . import curved_patch_provider_nodes as providers
from .curved_network_ownership_nodes import _compare

c = boundary.c
NAME = 'Prochitecture Streets / Whole attached Bundle boundary v1'


def _join_identities(g, reference, *parts):
    """Join only the same original vertex; restore its exact physical position."""
    joined = boundary._join(g, *parts)
    original = c.named(g, 'st_sb_original_vertex', 'INT')
    encoded = g.setpos(joined, g.xyz(original))
    weld = g.node('GeometryNodeMergeByDistance', 'Join original Bundle boundary identities')
    weld.inputs['Distance'].default_value = .1
    g.bind(encoded, weld.inputs['Geometry'])
    return g.setpos(weld.outputs['Geometry'],
        c._sample(g, reference, g.position(), original, 'FLOAT_VECTOR'))


def build():
    if NAME in bpy.data.node_groups:
        return bpy.data.node_groups[NAME]
    g = c.Graph(NAME)
    for key in ('Pavement', 'Corridors', 'Mouths'):
        g.socket(key, 'NodeSocketGeometry')
    for key in ('Member A', 'Member B', 'Head Patch', 'Tail Patch'):
        g.socket(key, 'NodeSocketInt')
    for key in ('Boundary', 'Side A', 'Side B', 'Head', 'Tail',
                'Inner A', 'Inner B', 'Members', 'Diagnostics'):
        g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    reference = c._store(g, inp.outputs['Pavement'], 'st_sb_original_vertex', index, 'INT')
    opening = g.node('GeometryNodeGroup', 'Original inner opening supplies the two patch bridges')
    opening.node_tree = closed.build(capture_wire=True)
    for key in ('Corridors', 'Mouths', 'Member A', 'Member B', 'Head Patch', 'Tail Patch'):
        g.bind(inp.outputs[key], opening.inputs[key])
    g.bind(reference, opening.inputs['Pavement'])
    valid = c.V(g, opening.outputs['Valid'])
    pieces = {}; heads = []; tails = []; members = []; metrics = {}
    keys = g.separate(c.named(g, '_bridge_key', 'FLOAT_VECTOR'))
    neighbors = g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']
    islands = g.node('GeometryNodeInputMeshIsland')
    edge = g.node('GeometryNodeInputMeshEdgeVertices')

    for member in ('A', 'B'):
        found, owner = providers._lookup(g, inp.outputs['Corridors'], 'st_cs_street_id', inp.outputs['Member '+member])
        split = g.node('GeometryNodeSeparateGeometry', 'Only original member '+member+' faces')
        split.domain = 'FACE'
        g.bind(reference, split.inputs['Geometry'])
        g.bind(_compare(g, c.named(g, 'st_cn_kind', 'INT'), 1)*
               _compare(g, c.named(g, 'st_cn_owner', 'INT'), owner), split.inputs['Selection'])
        mesh = split.outputs['Selection']; members.append(mesh)
        uses = g.node('GeometryNodeInputMeshEdgeNeighbors').outputs['Face Count']
        wire = closed._edges(g, mesh, _compare(g, uses, 1))
        end_rows = []; outer_anchors = []; at_head = []
        for side in ('start', 'end'):
            port = c._read(g, inp.outputs['Corridors'], 'st_cs_'+side+'_index', owner, 'INT')
            mouth_found, mouth = providers._lookup(g, inp.outputs['Mouths'], 'st_cj_input_index', port)
            half = c._read(g, inp.outputs['Mouths'], 'st_cj_half', mouth, 'INT')
            count = c._read(g, inp.outputs['Mouths'], 'st_cs_intervals', mouth, 'INT')
            same = _compare(g, keys[0], 0)*_compare(g, keys[1], port)
            inner = same*_compare(g, keys[2], .5*(half+1.)*count)
            outer = same*_compare(g, keys[2], .5*(1.-half)*count)
            outer_anchors.append(outer)
            touches = c._stat(g, opening.outputs['Head'], inner, 'Sum')
            at_head.append(_compare(g, touches, 1))
            row_edge = (c._sample(g, wire, same, edge.outputs['Vertex Index 1'], 'BOOLEAN')*
                        c._sample(g, wire, same, edge.outputs['Vertex Index 2'], 'BOOLEAN'))
            end_rows.append(row_edge)
            row = closed._edges(g, wire, row_edge)
            valid *= (mouth_found*_compare(g, g.math('ABSOLUTE', half), 1)*
                _compare(g, c._count(g, row), count+1.)*checks._chain_valid(g, row)*
                _compare(g, c._stat(g, row, outer, 'Sum'), 1)*
                _compare(g, c._stat(g, row, inner, 'Sum'), 1))
            if side == 'start':
                start_row = row
            else:
                end_row = row
        valid *= _compare(g, at_head[0]+at_head[1], 1)
        heads.append(c.choose(g, at_head[0], start_row, end_row, 'GEOMETRY'))
        tails.append(c.choose(g, at_head[0], end_row, start_row, 'GEOMETRY'))
        sides = closed._edges(g, wire, 1.-g.math('MAXIMUM', *end_rows))
        selected = c._stat(g, sides, outer_anchors[0]*c.V(g, islands.outputs['Island Index']), 'Sum')
        side = c._select(g, sides, _compare(g, islands.outputs['Island Index'], selected))
        inner_side = c._select(g, sides, 1.-_compare(g, islands.outputs['Island Index'], selected))
        pieces['Side '+member] = side; pieces['Inner '+member] = inner_side
        valid *= (found*checks._chain_valid(g, side)*checks._chain_valid(g, inner_side)*
            _compare(g, c._stat(g, sides, islands.outputs['Island Count'], 'Max'), 2))
        for endpoint in outer_anchors:
            valid *= _compare(g, c._stat(g, side, endpoint*_compare(g, neighbors, 1), 'Sum'), 1)
        metrics[member+'_outside_vertices'] = c._count(g, side)
    for key, rows in (('Head', heads), ('Tail', tails)):
        parts = (*rows, opening.outputs[key])
        pieces[key] = _join_identities(g, reference, *parts)
        valid *= checks._chain_valid(g, pieces[key])
        valid *= _compare(g, c._count(g, pieces[key]), sum(c._count(g, v) for v in parts)-2.)
        metrics[key.lower()+'_vertices'] = c._count(g, pieces[key])
    parts = [pieces[k] for k in ('Side A', 'Side B', 'Head', 'Tail')]
    footprint = checks._simple_footprint(g, reference, *parts)
    valid *= footprint
    pieces['Boundary'] = _join_identities(g, reference, *parts)
    pieces['Members'] = boundary._join(g, *members)
    record = c._line(g, 1)
    for key, value in metrics.items():
        record = c._store(g, record, 'st_bu_'+key, value, 'INT')
    record = c._store(g, record, 'st_bu_original_opening_valid', opening.outputs['Valid'], 'BOOLEAN')
    record = c._store(g, record, 'st_bu_footprint_valid', footprint, 'BOOLEAN')
    record = c._store(g, record, 'st_bu_boundary_valid', valid, 'BOOLEAN')
    for key, value in pieces.items():
        g.bind(boundary._empty(g, value, valid), out.inputs[key])
    g.bind(record, out.inputs['Diagnostics']); g.bind(valid, out.inputs['Valid'])
    return g.g


def chart():
    """Shared XY-only construction; callers must supply physical surface laws.

    The explicit Chart output has zero Z. It must not be published as a road:
    crown/plateau reconstruction, conforming grass regions and assembly are
    separate outstanding responsibilities. Original boundary outputs retain Z.
    """
    from . import curved_separator_surface_nodes as surface
    from . import curved_separator_quality_nodes as quality
    name = 'Prochitecture Streets / Whole attached Bundle XY chart v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Pavement', 'Corridors', 'Mouths'): g.socket(key, 'NodeSocketGeometry')
    for key in ('Member A', 'Member B', 'Head Patch', 'Tail Patch'): g.socket(key, 'NodeSocketInt')
    g.socket('Cell Size', 'NodeSocketFloat', default=.7)
    for key in ('Boundary', 'Side A', 'Side B', 'Head', 'Tail', 'Inner A', 'Inner B',
                'Boundary Diagnostics', 'Chart', 'Chart Diagnostics'):
        g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    for key in ('Boundary Valid', 'Chart Valid'): g.socket(key, 'NodeSocketBool', 'OUTPUT')
    g.socket('Edge Ratio', 'NodeSocketFloat', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    perimeter = g.node('GeometryNodeGroup'); perimeter.node_tree = build()
    for key in ('Pavement', 'Corridors', 'Mouths', 'Member A', 'Member B', 'Head Patch', 'Tail Patch'):
        g.bind(inp.outputs[key], perimeter.inputs[key])
    fill = g.node('GeometryNodeGroup', 'Direct quads in a temporary planar chart')
    fill.node_tree = surface.build(assembly=True, unequal_caps=True, quality_refinement=True)
    def flat(geometry):
        x, y, _ = g.separate(g.position())
        return c._store(g, g.setpos(geometry, g.xyz(x, y, 0.)), 'st_cn_height', 0.)
    g.bind(flat(inp.outputs['Pavement']), fill.inputs['Pavement'])
    for key in ('Side A', 'Side B', 'Head', 'Tail'): g.bind(flat(perimeter.outputs[key]), fill.inputs[key])
    g.bind(0, fill.inputs['Bundle ID']); g.bind(inp.outputs['Cell Size'], fill.inputs['Cell Size'])
    refined = g.node('GeometryNodeGroup', 'Bounded whole-width XY redistribution')
    refined.node_tree = quality.build(steps=256)
    g.bind(fill.outputs['Separator'], refined.inputs['Geometry'])
    valid = (c.V(g, perimeter.outputs['Valid'])*c.V(g, fill.outputs['Valid'])*
             (1.-g.math('GREATER_THAN', refined.outputs['After Ratio'], 8.)))
    for key in ('Boundary', 'Side A', 'Side B', 'Head', 'Tail', 'Inner A', 'Inner B'):
        g.bind(perimeter.outputs[key], out.inputs[key])
    g.bind(perimeter.outputs['Diagnostics'], out.inputs['Boundary Diagnostics'])
    g.bind(fill.outputs['Diagnostics'], out.inputs['Chart Diagnostics'])
    g.bind(refined.outputs['Geometry'], out.inputs['Chart'])
    g.bind(perimeter.outputs['Valid'], out.inputs['Boundary Valid'])
    g.bind(valid, out.inputs['Chart Valid'])
    g.bind(refined.outputs['After Ratio'], out.inputs['Edge Ratio'])
    g.g['st_xy_construction_only'] = True
    return g.g
